    .search-group {
      display: flex;
      align-items: center;
      border: 1px solid var(--border);
      border-radius: var(--radius-sm);
      background: #fff;
      transition: border-color 180ms ease, box-shadow 180ms ease;
      overflow: hidden;
    }

    .search-group:focus-within {
      border-color: var(--focus);
      box-shadow: 0 0 0 3px rgba(46, 111, 132, 0.2);
    }

    .search-input {
      flex: 1;
      border: 0;
      outline: none;
      min-height: 54px;
      padding: 0 16px;
      font-size: 1rem;
      color: var(--text);
    }

    .search-input::placeholder { color: #87939a; }

    .search-btn {
      border: 0;
      background: transparent;
      color: var(--primary);
      width: 56px;
      min-height: 54px;
      display: inline-grid;
      place-items: center;
      cursor: pointer;
