        flex-direction: column;
        align-items: stretch;
      }
      .cookie-btn { width: 100%; }
      .next { text-align: center; }
      .links { justify-content: center; }
    }

    @media (prefers-reduced-motion: reduce) {
      * { transition: none !important; }
    }
