</head>
<body>
  <main class="wrap" aria-labelledby="error-title">
    <div class="logo" aria-label="IdeaForum">
      <span class="logo-mark" aria-hidden="true"></span>
      <span>IdeaForum</span>
    </div>

    <h1 id="error-title">Sorry, we can't find that.</h1>
    <p class="lead">Perhaps we can help you find the content you're looking for:</p>

    <form class="search-form" id="searchForm" role="search" aria-label="Site search">
      <div class="search-group">
        <label for="searchInput" class="sr-only" style="position:absolute;left:-9999px;">Search IdeaForum</label>
        <input
          id="searchInput"
          class="search-input"
          name="q"
          type="search"
          placeholder="Search IdeaForum..."
          autocomplete="off"
          required
        />
        <button class="search-btn" type="submit" aria-label="Search">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" aria-hidden="true">
            <circle cx="11" cy="11" r="7" stroke="currentColor" stroke-width="2"></circle>
            <path d="M20 20L16.65 16.65" stroke="currentColor" stroke-width="2" stroke-linecap="round"></path>
          </svg>
        </button>
      </div>
    </form>

    <div class="code-strip">HTTP Error 404</div>
    <hr />

    <section class="next" aria-labelledby="next-title">
      <h2 id="next-title">What's next?</h2>
      <div class="links">
        <a href="homepage.html">Go to the homepage</a>
        <a href="help-desk.html">Visit our Help Desk</a>
      </div>
    </section>

    <div class="big-404" aria-hidden="true">404</div>
  </main>

  <aside class="cookie-banner" id="cookieBanner" aria-label="Cookie notice">
    <div class="cookie-inner">
      <p class="cookie-text">
        This website utilizes technologies such as cookies to enable essential site functionality, as well as for analytics, personalization, and targeted advertising. To learn more, view the following link:
        <a href="privacy-policy.html" target="_blank" rel="noopener noreferrer">Privacy Policy</a>
      </p>
      <button class="cookie-btn" id="managePrefsBtn" type="button">Manage Preferences</button>
    </div>
  </aside>

  <div class="modal-backdrop" id="prefsModal" role="dialog" aria-modal="true" aria-labelledby="prefsTitle">
    <div class="modal">
      <h3 id="prefsTitle">Cookie Preferences</h3>
      <p>Control how IdeaForum uses cookies and related technologies.</p>

      <div class="pref">
        <div class="pref-label">Essential Cookies<small>Required for core site functionality.</small></div>
        <label class="switch" aria-label="Essential cookies enabled">
          <input type="checkbox" checked disabled />
          <span class="slider"></span>
        </label>
      </div>

      <div class="pref">
        <div class="pref-label">Analytics Cookies<small>Help improve talks, events, and content discovery.</small></div>
        <label class="switch" aria-label="Toggle analytics cookies">
          <input type="checkbox" id="analyticsToggle" checked />
          <span class="slider"></span>
        </label>
      </div>

      <div class="pref">
        <div class="pref-label">Personalization Cookies<small>Tailor recommendations to your interests.</small></div>
        <label class="switch" aria-label="Toggle personalization cookies">
          <input type="checkbox" id="personalizationToggle" />
          <span class="slider"></span>
        </label>
      </div>

      <div class="modal-actions">
        <button class="ghost-btn" id="closeModalBtn" type="button">Cancel</button>
        <button class="primary-btn" id="savePrefsBtn" type="button">Save Preferences</button>
      </div>
    </div>
  </div>

  <script>
    const searchForm = document.getElementById('searchForm');
    const searchInput = document.getElementById('searchInput');
    const cookieBanner = document.getElementById('cookieBanner');
    const managePrefsBtn = document.getElementById('managePrefsBtn');
    const prefsModal = document.getElementById('prefsModal');
    const closeModalBtn = document.getElementById('closeModalBtn');
    const savePrefsBtn = document.getElementById('savePrefsBtn');

    const PREFS_KEY = 'ideaforum_cookie_prefs_v1';

    function openModal() {
      prefsModal.classList.add('show');
      closeModalBtn.focus();
    }

    function closeModal() {
      prefsModal.classList.remove('show');
      managePrefsBtn.focus();
    }

    function hideBanner() {
      cookieBanner.style.display = 'none';
    }

    function savePrefs() {
      const data = {
        analytics: document.getElementById('analyticsToggle').checked,
        personalization: document.getElementById('personalizationToggle').checked,
        savedAt: new Date().toISOString()
      };
      localStorage.setItem(PREFS_KEY, JSON.stringify(data));
      hideBanner();
      closeModal();
    }

    searchForm.addEventListener('submit', (event) => {
      event.preventDefault();
      const query = searchInput.value.trim();
      if (!query) return;
      window.location.href = `search-results.html?q=${encodeURIComponent(query)}`;
    });

    managePrefsBtn.addEventListener('click', openModal);
    closeModalBtn.addEventListener('click', closeModal);
    savePrefsBtn.addEventListener('click', savePrefs);

    prefsModal.addEventListener('click', (event) => {
      if (event.target === prefsModal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && prefsModal.classList.contains('show')) {
        closeModal();
      }
    });

    const existingPrefs = localStorage.getItem(PREFS_KEY);
    if (existingPrefs) {
      hideBanner();
      try {
        const parsed = JSON.parse(existingPrefs);
        if (typeof parsed.analytics === 'boolean') {
          document.getElementById('analyticsToggle').checked = parsed.analytics;
        }
        if (typeof parsed.personalization === 'boolean') {
          document.getElementById('personalizationToggle').checked = parsed.personalization;
        }
      } catch (_) {
      }
    }
  </script>
</body>
</html>
